mapper.select:
SELECT INPUT_NO, ITEM_NO, ITEM_NAME, ITEM_ID, ORDERNO, IS_USE, ITEM_TYPE, ACTIVITY, CPNY_ID
  FROM PA_ITEM_INPUT
 WHERE CPNY_ID  = #{cpnyId, jdbcType=VARCHAR}
   AND ACTIVITY = 1

   AND IS_USE   = #{isUse, jdbcType=NUMERIC}


   AND ITEM_TYPE = #{itemType, jdbcType=NUMERIC}

 ORDER BY ORDERNO, INPUT_NO

mapper.delete:
DELETE FROM PA_ITEM_INPUT
 WHERE CPNY_ID   = #{cpnyId,   jdbcType=VARCHAR}
   AND IS_USE    = #{isUse,    jdbcType=NUMERIC}
   AND ITEM_TYPE = #{itemType, jdbcType=NUMERIC}

mapper.select:
SELECT S.* FROM PA_SUMMARY_HAE S WHERE S.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND S.PAY_SCHEDULE_NO = #{payScheduleNo, jdbcType=VARCHAR}
AND EXISTS (SELECT 1 FROM HR_DEPARTMENT B1 WHERE B1.DEPTNO = S.DEPTNO START WITH B1.DEPTNO = #{deptNo, jdbcType=VARCHAR} CONNECT BY PRIOR B1.DEPTNO = B1.PARENT_DEPT_NO)
AND EXISTS (SELECT 1 FROM PA_SUPERVISOR_INFO PS WHERE PS.DEPTNO = S.DEPTNO AND PS.PERSON_ID = #{adminID, jdbcType=VARCHAR}) ORDER BY S.DEPT_ORDERNO, S.EMPID
